import{_ as i,o as a,c as e,ak as r}from"./chunks/framework.DvrM7GBU.js";const u=JSON.parse('{"title":"知识库扩展复盘与完善路线图","description":"","frontmatter":{},"headers":[],"relativePath":"知识库扩展复盘与完善路线图.md","filePath":"知识库扩展复盘与完善路线图.md","lastUpdated":1777893104000}'),h={name:"知识库扩展复盘与完善路线图.md"};function n(d,l,t,o,p,s){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="知识库扩展复盘与完善路线图" tabindex="-1">知识库扩展复盘与完善路线图 <a class="header-anchor" href="#知识库扩展复盘与完善路线图" aria-label="Permalink to “知识库扩展复盘与完善路线图”">​</a></h1><p>本文用于对当前知识库进行一次自我复盘，总结已经完成的结构、仍然存在的空白，以及后续如何把文档逐步扩展到更完整状态。</p><h2 id="_1-当前已经形成的结构" tabindex="-1">1. 当前已经形成的结构 <a class="header-anchor" href="#_1-当前已经形成的结构" aria-label="Permalink to “1. 当前已经形成的结构”">​</a></h2><p>截至目前，知识库已经不再是单纯的截图堆，而是初步形成了四层内容：</p><h3 id="第一层-总索引" tabindex="-1">第一层：总索引 <a class="header-anchor" href="#第一层-总索引" aria-label="Permalink to “第一层：总索引”">​</a></h3><ul><li><code>docs/知识库总索引.md</code></li></ul><p>作用：</p><ul><li>提供总入口</li><li>汇总文档位置</li><li>描述当前覆盖主题</li></ul><h3 id="第二层-主题知识文档" tabindex="-1">第二层：主题知识文档 <a class="header-anchor" href="#第二层-主题知识文档" aria-label="Permalink to “第二层：主题知识文档”">​</a></h3><p>包括：</p><ul><li>教程主题</li><li>脚本主题</li><li>引擎更新主题</li><li>社区分析主题</li></ul><p>作用：</p><ul><li>把零散资料升级成可读、可检索、可教学的结构化知识</li></ul><h3 id="第三层-ocr-转文本归档" tabindex="-1">第三层：OCR 转文本归档 <a class="header-anchor" href="#第三层-ocr-转文本归档" aria-label="Permalink to “第三层：OCR 转文本归档”">​</a></h3><p>包括：</p><ul><li>脚本界面截图 OCR</li><li>官方教程截图 OCR</li><li>引擎更新截图 OCR</li></ul><p>作用：</p><ul><li>保留原始证据</li><li>支持全文检索</li><li>支持后续人工校对</li></ul><h3 id="第四层-原始资料层" tabindex="-1">第四层：原始资料层 <a class="header-anchor" href="#第四层-原始资料层" aria-label="Permalink to “第四层：原始资料层”">​</a></h3><p>包括：</p><ul><li>历史整理记录中对应的 jpg 截图原图</li><li>原始 txt</li></ul><p>当前说明：</p><ul><li>本轮快照中原始资料目录结构仍保留，但未列出可直接 OCR 的图片文件</li><li>因此 jpg 截图应按“历史原图层 / 待恢复核验”理解，不应写成当前已完整可用</li></ul><p>作用：</p><ul><li>提供回溯依据</li><li>保留未整理信息</li></ul><hr><h2 id="_2-当前知识库的优点" tabindex="-1">2. 当前知识库的优点 <a class="header-anchor" href="#_2-当前知识库的优点" aria-label="Permalink to “2. 当前知识库的优点”">​</a></h2><h3 id="_2-1-已经有明显分层" tabindex="-1">2.1 已经有明显分层 <a class="header-anchor" href="#_2-1-已经有明显分层" aria-label="Permalink to “2.1 已经有明显分层”">​</a></h3><p>现在已经能区分：</p><ul><li>什么是原始证据</li><li>什么是整理索引</li><li>什么是专题解析</li><li>什么是社区推测</li></ul><p>这对后续长期维护很重要。</p><h3 id="_2-2-已经具备研究型文档雏形" tabindex="-1">2.2 已经具备研究型文档雏形 <a class="header-anchor" href="#_2-2-已经具备研究型文档雏形" aria-label="Permalink to “2.2 已经具备研究型文档雏形”">​</a></h3><p>目前一些文档已经不只是“写了截图内容”，而是开始解释：</p><ul><li>系统为何这样设计</li><li>组件与脚本的关系</li><li>UI 与联机的边界</li><li>数据与作用域的分层</li></ul><h3 id="_2-3-已经适合-ai-rag-初步使用" tabindex="-1">2.3 已经适合 AI/RAG 初步使用 <a class="header-anchor" href="#_2-3-已经适合-ai-rag-初步使用" aria-label="Permalink to “2.3 已经适合 AI/RAG 初步使用”">​</a></h3><p>许多文档已有：</p><ul><li>关键词</li><li>来源</li><li>结构化段落</li><li>主题归纳</li></ul><p>这意味着后续做问答、检索、向量化都更容易。</p><hr><h2 id="_3-当前仍然存在的不足" tabindex="-1">3. 当前仍然存在的不足 <a class="header-anchor" href="#_3-当前仍然存在的不足" aria-label="Permalink to “3. 当前仍然存在的不足”">​</a></h2><h3 id="_3-1-覆盖还不够完整" tabindex="-1">3.1 覆盖还不够完整 <a class="header-anchor" href="#_3-1-覆盖还不够完整" aria-label="Permalink to “3.1 覆盖还不够完整”">​</a></h3><p>虽然已经整理了不少主题，但整体仍然只是“有骨架”，还没完全补肉。</p><p>尤其是：</p><ul><li>脚本界面截图在历史 OCR 文档中仍有大量细节可继续分类、校对与回链；原图恢复后再继续新增 OCR</li><li>官方教程仍可拆出更多独立专题</li><li>引擎更新仍可继续按版本补来源与差异分析</li></ul><h3 id="_3-2-文档风格尚未完全统一" tabindex="-1">3.2 文档风格尚未完全统一 <a class="header-anchor" href="#_3-2-文档风格尚未完全统一" aria-label="Permalink to “3.2 文档风格尚未完全统一”">​</a></h3><p>目前文档虽然整体方向一致，但还可以进一步统一：</p><ul><li>术语</li><li>章节顺序</li><li>来源字段</li><li>关键词字段</li><li>版本字段</li><li>待验证标注</li></ul><h3 id="_3-3-已证实-推测-待验证-还没彻底区分" tabindex="-1">3.3 “已证实 / 推测 / 待验证”还没彻底区分 <a class="header-anchor" href="#_3-3-已证实-推测-待验证-还没彻底区分" aria-label="Permalink to “3.3 “已证实 / 推测 / 待验证”还没彻底区分”">​</a></h3><p>这是一个很重要的问题。</p><p>尤其在社区分析类文档中，后续应明确标记：</p><ul><li>官方明确说明</li><li>截图可直接证明</li><li>社区经验推断</li><li>需要实验验证</li></ul><p>否则知识库规模变大后，容易混淆结论等级。</p><hr><h2 id="_4-后续完善的核心方向" tabindex="-1">4. 后续完善的核心方向 <a class="header-anchor" href="#_4-后续完善的核心方向" aria-label="Permalink to “4. 后续完善的核心方向”">​</a></h2><h3 id="方向-a-补齐覆盖面" tabindex="-1">方向 A：补齐覆盖面 <a class="header-anchor" href="#方向-a-补齐覆盖面" aria-label="Permalink to “方向 A：补齐覆盖面”">​</a></h3><p>目标：</p><ul><li>原图恢复或重新盘点后，尽量把三大截图目录更多内容转成文本</li><li>当前无可 OCR 原图时，优先补现有 OCR 文档的状态词、映射表回链和专题引用</li><li>让知识库从“部分专题”走向“近乎完整覆盖”</li></ul><p>优先级：</p><ol><li>基础写脚本界面截图</li><li>官方教程文档截图</li><li>引擎更新说明截图</li></ol><h3 id="方向-b-补强深度" tabindex="-1">方向 B：补强深度 <a class="header-anchor" href="#方向-b-补强深度" aria-label="Permalink to “方向 B：补强深度”">​</a></h3><p>目标：</p><ul><li>不只写“有什么”</li><li>还要写“为什么这样设计”“如何正确使用”“会踩哪些坑”</li></ul><p>重点子系统：</p><ul><li>广播</li><li>UI</li><li>自定义组件</li><li>数据类型</li><li>作用域</li><li>地图与对象结构</li><li>联机同步</li></ul><h3 id="方向-c-补齐研究路线" tabindex="-1">方向 C：补齐研究路线 <a class="header-anchor" href="#方向-c-补齐研究路线" aria-label="Permalink to “方向 C：补齐研究路线”">​</a></h3><p>目标：</p><ul><li>把社区分析从“资料摘录”升级为“研究计划”</li><li>明确哪些问题可以继续实验验证</li></ul><hr><h2 id="_5-建议统一的文档模板" tabindex="-1">5. 建议统一的文档模板 <a class="header-anchor" href="#_5-建议统一的文档模板" aria-label="Permalink to “5. 建议统一的文档模板”">​</a></h2><p>为了让知识库越来越完整，建议后续尽量统一为以下结构：</p><ol><li>主题简介</li><li>资料来源</li><li>核心定义 / 核心现象</li><li>结构解析</li><li>使用方式 / 设计意义</li><li>常见误区 / 限制</li><li>版本差异（若有）</li><li>关键词</li><li>待验证问题</li></ol><p>这样会带来几个好处：</p><ul><li>阅读体验更统一</li><li>AI 更容易抽字段</li><li>后续自动化处理更容易</li></ul><hr><h2 id="_6-建议增加的辅助文档类型" tabindex="-1">6. 建议增加的辅助文档类型 <a class="header-anchor" href="#_6-建议增加的辅助文档类型" aria-label="Permalink to “6. 建议增加的辅助文档类型”">​</a></h2><p>除了当前已有文档类型，后续还可以增加：</p><h3 id="_6-1-问题清单型文档" tabindex="-1">6.1 问题清单型文档 <a class="header-anchor" href="#_6-1-问题清单型文档" aria-label="Permalink to “6.1 问题清单型文档”">​</a></h3><p>例如：</p><ul><li>常见误区清单</li><li>联机问题排查清单</li><li>UI 迁移检查清单</li></ul><h3 id="_6-2-对比型文档" tabindex="-1">6.2 对比型文档 <a class="header-anchor" href="#_6-2-对比型文档" aria-label="Permalink to “6.2 对比型文档”">​</a></h3><p>例如：</p><ul><li>3.x vs 4.x</li><li>地图属性 vs 系统属性</li><li>官方组件 vs 自定义组件</li><li>地图 UI vs 物体 UI</li></ul><h3 id="_6-3-时间线型文档" tabindex="-1">6.3 时间线型文档 <a class="header-anchor" href="#_6-3-时间线型文档" aria-label="Permalink to “6.3 时间线型文档”">​</a></h3><p>例如：</p><ul><li>联机 UI 演进时间线</li><li>数据类型演进时间线</li><li>调试工具演进时间线</li></ul><h3 id="_6-4-研究方法型文档" tabindex="-1">6.4 研究方法型文档 <a class="header-anchor" href="#_6-4-研究方法型文档" aria-label="Permalink to “6.4 研究方法型文档”">​</a></h3><p>例如：</p><ul><li>如何从截图做证据整理</li><li>如何区分观察结果与推测</li><li>如何设计创游实验验证流程</li></ul><hr><h2 id="_7-建议增加-完整度状态-概念" tabindex="-1">7. 建议增加“完整度状态”概念 <a class="header-anchor" href="#_7-建议增加-完整度状态-概念" aria-label="Permalink to “7. 建议增加“完整度状态”概念”">​</a></h2><p>为了让知识库更容易持续维护，建议以后给重点主题加一个大致状态：</p><ul><li>草稿</li><li>已整理</li><li>深度整理</li><li>持续扩展中</li><li>近完整</li></ul><p>例如：</p><ul><li>广播机制：深度整理</li><li>联机 UI：持续扩展中</li><li>引擎更新全版本：持续扩展中</li><li>脚本界面全量 OCR：持续扩展中</li></ul><p>这样做的好处是：</p><ul><li>一眼看出哪里还没做完</li><li>更容易排优先级</li><li>不会误以为某些文档已经彻底完善</li></ul><hr><h2 id="_8-当前最值得继续扩展的专题" tabindex="-1">8. 当前最值得继续扩展的专题 <a class="header-anchor" href="#_8-当前最值得继续扩展的专题" aria-label="Permalink to “8. 当前最值得继续扩展的专题”">​</a></h2><h3 id="脚本与界面方向" tabindex="-1">脚本与界面方向 <a class="header-anchor" href="#脚本与界面方向" aria-label="Permalink to “脚本与界面方向”">​</a></h3><ul><li>装置/机关组件深度研究</li><li>显示类组件深度研究</li><li>交互类组件深度研究</li><li>地图级脚本能力深度研究</li><li>脚本作用域与数据流深度研究（已开）</li></ul><h3 id="教程方向" tabindex="-1">教程方向 <a class="header-anchor" href="#教程方向" aria-label="Permalink to “教程方向”">​</a></h3><ul><li>广播机制深度解析（已开）</li><li>道具组件深度解析</li><li>子弹组件深度解析</li><li>地块组件深度解析</li><li>素材系统与实例化关系扩写</li></ul><h3 id="引擎更新方向" tabindex="-1">引擎更新方向 <a class="header-anchor" href="#引擎更新方向" aria-label="Permalink to “引擎更新方向”">​</a></h3><ul><li>联机 UI 演进专题（已开）</li><li>数据类型演进专题</li><li>调试工具演进专题</li><li>编辑器工作流优化专题</li><li>兼容性与版本隔离专题</li></ul><h3 id="社区研究方向" tabindex="-1">社区研究方向 <a class="header-anchor" href="#社区研究方向" aria-label="Permalink to “社区研究方向”">​</a></h3><ul><li>3.x 与 4.x 可观察性差异（已开）</li><li>社区逆向研究问题清单</li><li>伪源码字段字典</li><li>类型转换实验路线图</li></ul><hr><h2 id="_9-对-完整状态-的理解" tabindex="-1">9. 对“完整状态”的理解 <a class="header-anchor" href="#_9-对-完整状态-的理解" aria-label="Permalink to “9. 对“完整状态”的理解”">​</a></h2><p>所谓完整，不一定是“所有截图一个字不漏全抄完”，而更像：</p><h3 id="证据层完整" tabindex="-1">证据层完整 <a class="header-anchor" href="#证据层完整" aria-label="Permalink to “证据层完整”">​</a></h3><ul><li>关键截图大部分都有 OCR 与来源记录</li></ul><h3 id="主题层完整" tabindex="-1">主题层完整 <a class="header-anchor" href="#主题层完整" aria-label="Permalink to “主题层完整”">​</a></h3><ul><li>主要系统都有独立专题</li></ul><h3 id="结构层完整" tabindex="-1">结构层完整 <a class="header-anchor" href="#结构层完整" aria-label="Permalink to “结构层完整”">​</a></h3><ul><li>文档彼此之间能互相链接、互相解释</li></ul><h3 id="研究层完整" tabindex="-1">研究层完整 <a class="header-anchor" href="#研究层完整" aria-label="Permalink to “研究层完整”">​</a></h3><ul><li>已知事实、推测、待验证路线能清晰分开</li></ul><p>如果能达到这四点，知识库就已经非常成熟。</p><hr><h2 id="_10-本轮复盘新增结论" tabindex="-1">10. 本轮复盘新增结论 <a class="header-anchor" href="#_10-本轮复盘新增结论" aria-label="Permalink to “10. 本轮复盘新增结论”">​</a></h2><p>经过本轮继续体检，可以更明确地看到几个问题类型：</p><h3 id="_10-1-结构型问题" tabindex="-1">10.1 结构型问题 <a class="header-anchor" href="#_10-1-结构型问题" aria-label="Permalink to “10.1 结构型问题”">​</a></h3><ul><li>新增高价值文档后，旧专题不一定会自动回链，容易形成“新文档强、旧文档弱连接”的问题</li><li>总索引需要承担的不只是目录，还应承担阅读路线与聚合入口</li></ul><h3 id="_10-2-工程型问题" tabindex="-1">10.2 工程型问题 <a class="header-anchor" href="#_10-2-工程型问题" aria-label="Permalink to “10.2 工程型问题”">​</a></h3><ul><li>文档头字段在持续扩写后容易出现日期、完整度状态、来源文件不一致</li><li>OCR 工程文档容易出现统计更新了，但状态描述没同步的情况</li></ul><h3 id="_10-3-内容型问题" tabindex="-1">10.3 内容型问题 <a class="header-anchor" href="#_10-3-内容型问题" aria-label="Permalink to “10.3 内容型问题”">​</a></h3><ul><li>旧专题往往知识是对的，但关联阅读不足，导致项目型价值没有完全释放</li><li>研究型文档与规范型文档之间还需要更多互链，才能真正适合 AI/RAG 长期使用</li></ul><hr><h2 id="_11-本轮已执行的自我修复动作" tabindex="-1">11. 本轮已执行的自我修复动作 <a class="header-anchor" href="#_11-本轮已执行的自我修复动作" aria-label="Permalink to “11. 本轮已执行的自我修复动作”">​</a></h2><p>为了避免复盘只停留在“说问题”，本轮已经实际执行了以下修复：</p><ol><li><p><strong>README 升级</strong></p><ul><li>增加快速导航</li><li>增加主题入口</li><li>增加阅读建议</li><li>增加维护说明</li></ul></li><li><p><strong>待验证问题清单增强</strong></p><ul><li>增加 P0 / P1 / P2 优先级</li><li>增加修复闭环</li><li>增加自我复盘说明</li></ul></li><li><p><strong>OCR 映射表边界修正</strong></p><ul><li>清理“待补专题”式表述</li><li>改成“研究计划项 / 处理建议”</li><li>降低索引文档与研究文档混淆</li></ul></li></ol><p>这些动作说明当前复盘不是空转，而是已经开始形成“发现问题 → 修正表达 → 回写结构”的闭环。</p><hr><h2 id="_12-下一轮最值得继续修的点" tabindex="-1">12. 下一轮最值得继续修的点 <a class="header-anchor" href="#_12-下一轮最值得继续修的点" aria-label="Permalink to “12. 下一轮最值得继续修的点”">​</a></h2><p>如果继续深度优化，下一轮建议优先做：</p><h3 id="_12-1-把总索引进一步升级成导航中枢" tabindex="-1">12.1 把总索引进一步升级成导航中枢 <a class="header-anchor" href="#_12-1-把总索引进一步升级成导航中枢" aria-label="Permalink to “12.1 把总索引进一步升级成导航中枢”">​</a></h3><p>目标不是只列文件，而是：</p><ul><li>能按主题找</li><li>能按问题找</li><li>能按证据层级找</li><li>能按成熟度找</li></ul><h3 id="_12-2-给成熟文档重新评级" tabindex="-1">12.2 给成熟文档重新评级 <a class="header-anchor" href="#_12-2-给成熟文档重新评级" aria-label="Permalink to “12.2 给成熟文档重新评级”">​</a></h3><p>例如把部分文档从“持续扩展中”改成：</p><ul><li>深度整理</li><li>近完整</li></ul><p>这样可以提升全库状态表达的可信度和辨识度。</p><h3 id="_12-3-清洗-ocr-文档状态词的一致性" tabindex="-1">12.3 清洗 OCR 文档状态词的一致性 <a class="header-anchor" href="#_12-3-清洗-ocr-文档状态词的一致性" aria-label="Permalink to “12.3 清洗 OCR 文档状态词的一致性”">​</a></h3><p>尤其是：</p><ul><li>无有效文本</li><li>待复核</li><li>疑似重复页</li><li>待处理</li></ul><p>这些状态如果定义更一致，后续做自动统计或 AI 检索会更稳。</p><h3 id="_12-4-给高价值专题补更多回链" tabindex="-1">12.4 给高价值专题补更多回链 <a class="header-anchor" href="#_12-4-给高价值专题补更多回链" aria-label="Permalink to “12.4 给高价值专题补更多回链”">​</a></h3><p>优先补：</p><ul><li>来源文件</li><li>对应截图编号</li><li>对应 OCR 文档</li><li>关联阅读</li></ul><hr><h2 id="_13-总结" tabindex="-1">13. 总结 <a class="header-anchor" href="#_13-总结" aria-label="Permalink to “13. 总结”">​</a></h2><p>当前知识库已经从“资料整理”进入“系统化扩写”阶段。</p><p>下一阶段最重要的，不再只是继续堆内容，而是同时做好三件事：</p><ul><li>扩覆盖</li><li>补深度</li><li>统一结构</li></ul><p>只要持续沿这条路线推进，最后会得到一个：</p><ul><li>可检索</li><li>可教学</li><li>可追溯</li><li>可研究</li><li>适合 AI 使用</li></ul><p>的完整知识库。</p>',157)])])}const b=i(h,[["render",n]]);export{u as __pageData,b as default};
